"""A small HDL parser and event-driven simulator for the nand2tetris HDL.

Chip resolution mirrors the official Hardware Simulator: a part name is looked
up as ``<Name>.hdl`` in the directory of the chip being loaded and, failing
that, resolves to the built-in implementation from ``builtins.py``.

Buses are flattened to single-bit nodes.  Every leaf instance is a built-in;
user-defined chips are expanded in place with their pins aliased onto the
enclosing chip's nodes.  When one output pin feeds several wires
(``ALU(out=outM, out=aluOut)``) the wires are merged with a union-find pass
after expansion.
"""

import os
import re
from collections import deque

from . import builtins as bi

CONST0 = 0
CONST1 = 1


class HDLError(Exception):
    pass


# ---------------------------------------------------------------------------
# parsing
# ---------------------------------------------------------------------------

_COMMENT_RE = re.compile(r'//[^\n]*|/\*.*?\*/', re.S)


class PinDecl:
    __slots__ = ('name', 'width')

    def __init__(self, name, width):
        self.name = name
        self.width = width


class Part:
    __slots__ = ('chip', 'conns')

    def __init__(self, chip, conns):
        self.chip = chip
        self.conns = conns  # list of (pin, pin_slice, wire, wire_slice)


class ChipDef:
    def __init__(self, name, ins, outs, parts, path):
        self.name = name
        self.ins = ins
        self.outs = outs
        self.parts = parts
        self.path = path
        self.in_width = {p.name: p.width for p in ins}
        self.out_width = {p.name: p.width for p in outs}


def _strip_comments(text):
    return _COMMENT_RE.sub(' ', text)


def _parse_pin_list(text):
    pins = []
    for item in text.split(','):
        item = item.strip()
        if not item:
            continue
        m = re.fullmatch(r'([A-Za-z_][\w.]*)\s*(?:\[\s*(\d+)\s*\])?', item)
        if not m:
            raise HDLError('bad pin declaration: %r' % item)
        pins.append(PinDecl(m.group(1), int(m.group(2) or 1)))
    return pins


def _parse_ref(text):
    """Parse ``name``/``name[i]``/``name[i..j]`` into ``(name, slice_or_None)``."""
    text = text.strip()
    m = re.fullmatch(
        r'([A-Za-z_][\w.]*)\s*(?:\[\s*(\d+)\s*(?:\.\.\s*(\d+)\s*)?\])?', text)
    if not m:
        raise HDLError('bad pin reference: %r' % text)
    name = m.group(1)
    if m.group(2) is None:
        return name, None
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) is not None else lo
    if hi < lo:
        raise HDLError('inverted bus range: %r' % text)
    return name, (lo, hi)


def parse_hdl(path):
    with open(path) as fh:
        text = _strip_comments(fh.read())

    m = re.search(r'CHIP\s+([A-Za-z_]\w*)\s*\{(.*)\}', text, re.S)
    if not m:
        raise HDLError('%s: no CHIP definition found' % path)
    name, body = m.group(1), m.group(2)

    ins, outs = [], []
    m_in = re.search(r'\bIN\b(.*?);', body, re.S)
    if m_in:
        ins = _parse_pin_list(m_in.group(1))
    m_out = re.search(r'\bOUT\b(.*?);', body, re.S)
    if m_out:
        outs = _parse_pin_list(m_out.group(1))

    m_parts = re.search(r'\bPARTS:\s*(.*)$', body, re.S)
    parts_text = m_parts.group(1) if m_parts else ''
    if 'TODO' in parts_text:
        raise HDLError('%s: chip body is still a stub' % path)
    parts = []
    for stmt in parts_text.split(';'):
        stmt = stmt.strip()
        if not stmt:
            continue
        pm = re.fullmatch(r'([A-Za-z_]\w*)\s*\((.*)\)', stmt, re.S)
        if not pm:
            raise HDLError('%s: cannot parse part %r' % (path, stmt))
        chip = pm.group(1)
        conns = []
        for conn in pm.group(2).split(','):
            conn = conn.strip()
            if not conn:
                continue
            if '=' not in conn:
                raise HDLError('%s: bad connection %r' % (path, conn))
            left, right = conn.split('=', 1)
            pin, pin_sl = _parse_ref(left)
            wire, wire_sl = _parse_ref(right)
            conns.append((pin, pin_sl, wire, wire_sl))
        parts.append(Part(chip, conns))
    return ChipDef(name, ins, outs, parts, path)


# ---------------------------------------------------------------------------
# netlist
# ---------------------------------------------------------------------------

class Instance:
    __slots__ = ('chip', 'kind', 'fn', 'obj', 'ins', 'outs', 'index')

    def __init__(self, chip, kind, fn, obj, ins, outs, index):
        self.chip = chip
        self.kind = kind          # 'comb' or 'seq'
        self.fn = fn
        self.obj = obj
        self.ins = ins            # {pin: [node, ...]} LSB first
        self.outs = outs
        self.index = index


class Simulator:
    """Loads a chip from an .hdl file and simulates it."""

    MAX_STEPS = 5000000

    def __init__(self, hdl_path, search_dirs=None):
        self.hdl_path = os.path.abspath(hdl_path)
        self.dir = os.path.dirname(self.hdl_path)
        self.search_dirs = [self.dir] + [os.path.abspath(d)
                                         for d in (search_dirs or [])]
        self._chip_cache = {}
        self.values = [0, 1]
        self._parent = [0, 1]
        self.instances = []
        self.by_chip = {}
        self.readers = {}

        self.chip = self._load_chip_file(self.hdl_path)
        self.pin_nodes = {}
        for p in self.chip.ins:
            self.pin_nodes[p.name] = self._new_nodes(p.width)
        for p in self.chip.outs:
            self.pin_nodes[p.name] = self._new_nodes(p.width)
        self.pin_width = dict(self.chip.in_width)
        self.pin_width.update(self.chip.out_width)
        self.input_pins = {p.name for p in self.chip.ins}
        self._expand(self.chip, self.pin_nodes)
        self._finalize()
        self.seq_indices = [i for i, inst in enumerate(self.instances)
                            if inst.kind == 'seq']
        self.eval_all()

    # -- nodes ------------------------------------------------------------
    def _new_node(self):
        self.values.append(0)
        self._parent.append(len(self.values) - 1)
        return len(self.values) - 1

    def _new_nodes(self, n):
        return [self._new_node() for _ in range(n)]

    def _find(self, n):
        p = self._parent
        root = n
        while p[root] != root:
            root = p[root]
        while p[n] != root:
            p[n], n = root, p[n]
        return root

    def _union(self, a, b):
        ra, rb = self._find(a), self._find(b)
        if ra == rb:
            return
        # keep the lower id (so constants 0/1 always win) as representative
        if rb < ra:
            ra, rb = rb, ra
        self._parent[rb] = ra

    # -- chip resolution --------------------------------------------------
    def _load_chip_file(self, path):
        if path not in self._chip_cache:
            self._chip_cache[path] = parse_hdl(path)
        return self._chip_cache[path]

    def _resolve(self, name):
        """Return a ChipDef for a user chip, or None when it is built-in."""
        for d in self.search_dirs:
            cand = os.path.join(d, name + '.hdl')
            if os.path.exists(cand):
                return self._load_chip_file(cand)
        if bi.is_builtin(name):
            return None
        raise HDLError('unknown chip: %s' % name)

    def _interface(self, name):
        chip = self._resolve(name)
        if chip is None:
            ins, outs = bi.builtin_interface(name)
            return ({n: w for n, w in ins}, {n: w for n, w in outs}, None)
        return (dict(chip.in_width), dict(chip.out_width), chip)

    # -- expansion --------------------------------------------------------
    def _add_instance(self, chip, ins, outs):
        idx = len(self.instances)
        if chip in bi.COMBINATIONAL:
            _, _, fn = bi.COMBINATIONAL[chip]
            inst = Instance(chip, 'comb', fn, None, ins, outs, idx)
        else:
            inst = Instance(chip, 'seq', None, bi.SEQUENTIAL[chip](),
                            ins, outs, idx)
        self.instances.append(inst)
        self.by_chip.setdefault(chip, []).append(inst)
        return inst

    def _expand(self, chip, pin_nodes):
        wires = dict(pin_nodes)
        widths = {}
        for p in chip.ins:
            widths[p.name] = p.width
        for p in chip.outs:
            widths[p.name] = p.width

        parts_meta = []
        for part in chip.parts:
            in_w, out_w, sub = self._interface(part.chip)
            parts_meta.append((part, in_w, out_w, sub))
            for pin, pin_sl, wire, wire_sl in part.conns:
                if wire in ('true', 'false'):
                    continue
                if pin in in_w:
                    pw = in_w[pin]
                elif pin in out_w:
                    pw = out_w[pin]
                else:
                    raise HDLError('%s: chip %s has no pin %s'
                                   % (chip.name, part.chip, pin))
                span = (pin_sl[1] - pin_sl[0] + 1) if pin_sl else pw
                need = (wire_sl[1] + 1) if wire_sl else span
                widths[wire] = max(widths.get(wire, 0), need)

        for name, w in sorted(widths.items()):
            if name not in wires:
                wires[name] = self._new_nodes(w)

        def wire_nodes(wire, wire_sl, span):
            if wire == 'true':
                return [CONST1] * span
            if wire == 'false':
                return [CONST0] * span
            nodes = wires[wire]
            if wire_sl is None:
                sel = nodes[:span]
            else:
                sel = nodes[wire_sl[0]:wire_sl[1] + 1]
            if len(sel) != span:
                raise HDLError('%s: width mismatch on wire %s (%d vs %d)'
                               % (chip.name, wire, len(sel), span))
            return sel

        for part, in_w, out_w, sub in parts_meta:
            sub_in = {p: [CONST0] * w for p, w in in_w.items()}
            out_conns = {}
            for pin, pin_sl, wire, wire_sl in part.conns:
                if pin in in_w:
                    pw = in_w[pin]
                    lo, hi = (pin_sl if pin_sl else (0, pw - 1))
                    src = wire_nodes(wire, wire_sl, hi - lo + 1)
                    cur = sub_in[pin]
                    sub_in[pin] = cur[:lo] + src + cur[hi + 1:]
                else:
                    pw = out_w[pin]
                    lo, hi = (pin_sl if pin_sl else (0, pw - 1))
                    dst = wire_nodes(wire, wire_sl, hi - lo + 1)
                    out_conns.setdefault(pin, []).append((lo, dst))

            sub_out = {}
            for pin, w in out_w.items():
                nodes = [None] * w
                for lo, dst in out_conns.get(pin, []):
                    for i, n in enumerate(dst):
                        if nodes[lo + i] is None:
                            nodes[lo + i] = n
                        else:
                            self._union(nodes[lo + i], n)
                for i in range(w):
                    if nodes[i] is None:
                        nodes[i] = self._new_node()
                sub_out[pin] = nodes

            if sub is None:
                self._add_instance(part.chip, sub_in, sub_out)
            else:
                child_pins = dict(sub_in)
                child_pins.update(sub_out)
                self._expand(sub, child_pins)

    def _finalize(self):
        f = self._find
        for inst in self.instances:
            inst.ins = {p: [f(n) for n in nodes]
                        for p, nodes in inst.ins.items()}
            inst.outs = {p: [f(n) for n in nodes]
                         for p, nodes in inst.outs.items()}
        self.pin_nodes = {p: [f(n) for n in nodes]
                          for p, nodes in self.pin_nodes.items()}
        readers = {}
        for inst in self.instances:
            seen = set()
            for nodes in inst.ins.values():
                for n in nodes:
                    if n not in seen:
                        seen.add(n)
                        readers.setdefault(n, []).append(inst.index)
        self.readers = readers

    # -- evaluation -------------------------------------------------------
    def _read(self, nodes):
        v = 0
        values = self.values
        for i, n in enumerate(nodes):
            if values[n]:
                v |= 1 << i
        return v

    def _propagate(self, seeds):
        values = self.values
        instances = self.instances
        readers = self.readers
        queued = bytearray(len(instances))
        dq = deque()
        for i in seeds:
            if not queued[i]:
                queued[i] = 1
                dq.append(i)
        steps = 0
        while dq:
            steps += 1
            if steps > self.MAX_STEPS:
                raise HDLError('combinational loop detected in %s'
                               % self.chip.name)
            idx = dq.popleft()
            queued[idx] = 0
            inst = instances[idx]
            vals = {}
            for pin, nodes in inst.ins.items():
                v = 0
                for i, n in enumerate(nodes):
                    if values[n]:
                        v |= 1 << i
                vals[pin] = v
            outs = (inst.fn(vals) if inst.kind == 'comb'
                    else inst.obj.combinational(vals))
            for pin, value in outs.items():
                for i, n in enumerate(inst.outs[pin]):
                    b = (value >> i) & 1
                    if values[n] != b:
                        values[n] = b
                        for r in readers.get(n, ()):
                            if not queued[r]:
                                queued[r] = 1
                                dq.append(r)
        return steps

    def eval_all(self):
        self._propagate(range(len(self.instances)))

    eval = eval_all

    def set_pin(self, name, value):
        if name not in self.pin_nodes:
            raise HDLError('%s: no such pin: %s' % (self.chip.name, name))
        nodes = self.pin_nodes[name]
        seeds = []
        for i, n in enumerate(nodes):
            b = (value >> i) & 1
            if self.values[n] != b:
                self.values[n] = b
                seeds.extend(self.readers.get(n, ()))
        self._propagate(seeds)

    def get_pin(self, name):
        return self._read(self.pin_nodes[name])

    def tick(self):
        for i in self.seq_indices:
            inst = self.instances[i]
            vals = {pin: self._read(nodes) for pin, nodes in inst.ins.items()}
            inst.obj.clock_up(vals)

    def tock(self):
        for i in self.seq_indices:
            self.instances[i].obj.clock_down()
        self._propagate(self.seq_indices)

    # -- internal state access -------------------------------------------
    def find_chip(self, name):
        insts = self.by_chip.get(name)
        if not insts:
            raise HDLError('no built-in %s instance inside %s'
                           % (name, self.chip.name))
        return insts[0].obj

    def get_internal(self, name, index):
        return self.find_chip(name).get_value(index)

    def set_internal(self, name, index, value):
        self.find_chip(name).set_value(value, index)
        self.eval_all()

"""Native ("built-in") implementations of the standard nand2tetris chip set.

The official Hardware Simulator resolves a chip-part name by looking for
`<Name>.hdl` in the directory of the chip being loaded; when that file does
not exist it falls back to the built-in implementation.  This module supplies
those built-in implementations so the same resolution rule can be used here.

Conventions
-----------
* Pin values are plain Python ints holding an unsigned bit pattern.
* Combinational chips are described by ``COMBINATIONAL[name] = (ins, outs, fn)``
  where ``ins``/``outs`` are ``[(pin, width), ...]`` and ``fn`` maps a dict of
  input values to a dict of output values.
* Clocked chips are classes exposing ``combinational``, ``clock_up`` and
  ``clock_down`` (see ``SequentialChip``).
"""

W16 = 0xFFFF


def _mask(v, width):
    return v & ((1 << width) - 1)


def _bits16(v):
    return [(v >> i) & 1 for i in range(16)]


def _from_bits(bits):
    v = 0
    for i, b in enumerate(bits):
        if b:
            v |= 1 << i
    return v


# ---------------------------------------------------------------------------
# combinational built-ins
# ---------------------------------------------------------------------------

COMBINATIONAL = {}


def _comb(name, ins, outs):
    def deco(fn):
        COMBINATIONAL[name] = (ins, outs, fn)
        return fn
    return deco


@_comb('Nand', [('a', 1), ('b', 1)], [('out', 1)])
def _nand(v):
    return {'out': 1 - (v['a'] & v['b'])}


@_comb('Not', [('in', 1)], [('out', 1)])
def _not(v):
    return {'out': 1 - v['in']}


@_comb('And', [('a', 1), ('b', 1)], [('out', 1)])
def _and(v):
    return {'out': v['a'] & v['b']}


@_comb('Or', [('a', 1), ('b', 1)], [('out', 1)])
def _or(v):
    return {'out': v['a'] | v['b']}


@_comb('Xor', [('a', 1), ('b', 1)], [('out', 1)])
def _xor(v):
    return {'out': v['a'] ^ v['b']}


@_comb('Mux', [('a', 1), ('b', 1), ('sel', 1)], [('out', 1)])
def _mux(v):
    return {'out': v['b'] if v['sel'] else v['a']}


@_comb('DMux', [('in', 1), ('sel', 1)], [('a', 1), ('b', 1)])
def _dmux(v):
    return {'a': 0 if v['sel'] else v['in'], 'b': v['in'] if v['sel'] else 0}


@_comb('Not16', [('in', 16)], [('out', 16)])
def _not16(v):
    return {'out': (~v['in']) & W16}


@_comb('And16', [('a', 16), ('b', 16)], [('out', 16)])
def _and16(v):
    return {'out': v['a'] & v['b']}


@_comb('Or16', [('a', 16), ('b', 16)], [('out', 16)])
def _or16(v):
    return {'out': v['a'] | v['b']}


@_comb('Mux16', [('a', 16), ('b', 16), ('sel', 1)], [('out', 16)])
def _mux16(v):
    return {'out': v['b'] if v['sel'] else v['a']}


@_comb('Or8Way', [('in', 8)], [('out', 1)])
def _or8way(v):
    return {'out': 1 if v['in'] else 0}


@_comb('Mux4Way16',
       [('a', 16), ('b', 16), ('c', 16), ('d', 16), ('sel', 2)],
       [('out', 16)])
def _mux4way16(v):
    return {'out': [v['a'], v['b'], v['c'], v['d']][v['sel']]}


@_comb('Mux8Way16',
       [('a', 16), ('b', 16), ('c', 16), ('d', 16),
        ('e', 16), ('f', 16), ('g', 16), ('h', 16), ('sel', 3)],
       [('out', 16)])
def _mux8way16(v):
    return {'out': [v['a'], v['b'], v['c'], v['d'],
                    v['e'], v['f'], v['g'], v['h']][v['sel']]}


@_comb('DMux4Way', [('in', 1), ('sel', 2)],
       [('a', 1), ('b', 1), ('c', 1), ('d', 1)])
def _dmux4way(v):
    out = {'a': 0, 'b': 0, 'c': 0, 'd': 0}
    out['abcd'[v['sel']]] = v['in']
    return out


@_comb('DMux8Way', [('in', 1), ('sel', 3)],
       [('a', 1), ('b', 1), ('c', 1), ('d', 1),
        ('e', 1), ('f', 1), ('g', 1), ('h', 1)])
def _dmux8way(v):
    out = {k: 0 for k in 'abcdefgh'}
    out['abcdefgh'[v['sel']]] = v['in']
    return out


@_comb('HalfAdder', [('a', 1), ('b', 1)], [('sum', 1), ('carry', 1)])
def _halfadder(v):
    return {'sum': v['a'] ^ v['b'], 'carry': v['a'] & v['b']}


@_comb('FullAdder', [('a', 1), ('b', 1), ('c', 1)],
       [('sum', 1), ('carry', 1)])
def _fulladder(v):
    s = v['a'] + v['b'] + v['c']
    return {'sum': s & 1, 'carry': 1 if s > 1 else 0}


@_comb('Add16', [('a', 16), ('b', 16)], [('out', 16)])
def _add16(v):
    return {'out': (v['a'] + v['b']) & W16}


@_comb('Inc16', [('in', 16)], [('out', 16)])
def _inc16(v):
    return {'out': (v['in'] + 1) & W16}


@_comb('ALU',
       [('x', 16), ('y', 16), ('zx', 1), ('nx', 1),
        ('zy', 1), ('ny', 1), ('f', 1), ('no', 1)],
       [('out', 16), ('zr', 1), ('ng', 1)])
def _alu(v):
    x, y = v['x'], v['y']
    if v['zx']:
        x = 0
    if v['nx']:
        x = (~x) & W16
    if v['zy']:
        y = 0
    if v['ny']:
        y = (~y) & W16
    out = (x + y) & W16 if v['f'] else (x & y)
    if v['no']:
        out = (~out) & W16
    return {'out': out,
            'zr': 1 if out == 0 else 0,
            'ng': 1 if out & 0x8000 else 0}


# ---------------------------------------------------------------------------
# clocked built-ins
# ---------------------------------------------------------------------------

class SequentialChip:
    """Base class for clocked built-in chips.

    Timing follows the official simulator: ``clock_up`` (tick) latches the
    inputs without changing any output, ``clock_down`` (tock) commits the
    latched value so that it becomes visible on the outputs.
    """

    INS = []
    OUTS = []

    def combinational(self, v):
        raise NotImplementedError

    def clock_up(self, v):
        pass

    def clock_down(self):
        pass


SEQUENTIAL = {}


def _seq(name):
    def deco(cls):
        SEQUENTIAL[name] = cls
        cls.CHIP_NAME = name
        return cls
    return deco


@_seq('DFF')
class DFFChip(SequentialChip):
    INS = [('in', 1)]
    OUTS = [('out', 1)]

    def __init__(self):
        self.state = 0
        self.pending = 0

    def combinational(self, v):
        return {'out': self.state}

    def clock_up(self, v):
        self.pending = v['in']

    def clock_down(self):
        self.state = self.pending

    def get_value(self, index=None):
        return self.state

    def set_value(self, value, index=None):
        self.state = value & 1
        self.pending = self.state


class _RegisterLike(SequentialChip):
    WIDTH = 16
    INS = [('in', 16), ('load', 1)]
    OUTS = [('out', 16)]

    def __init__(self):
        self.state = 0
        self.pending = 0

    def combinational(self, v):
        return {'out': self.state}

    def clock_up(self, v):
        self.pending = v['in'] if v['load'] else self.state

    def clock_down(self):
        self.state = self.pending

    def get_value(self, index=None):
        return self.state

    def set_value(self, value, index=None):
        self.state = _mask(value, self.WIDTH)
        self.pending = self.state


@_seq('Bit')
class BitChip(_RegisterLike):
    WIDTH = 1
    INS = [('in', 1), ('load', 1)]
    OUTS = [('out', 1)]


@_seq('Register')
class RegisterChip(_RegisterLike):
    pass


@_seq('ARegister')
class ARegisterChip(_RegisterLike):
    pass


@_seq('DRegister')
class DRegisterChip(_RegisterLike):
    pass


@_seq('PC')
class PCChip(SequentialChip):
    INS = [('in', 16), ('load', 1), ('inc', 1), ('reset', 1)]
    OUTS = [('out', 16)]

    def __init__(self):
        self.state = 0
        self.pending = 0

    def combinational(self, v):
        return {'out': self.state}

    def clock_up(self, v):
        if v['reset']:
            self.pending = 0
        elif v['load']:
            self.pending = v['in']
        elif v['inc']:
            self.pending = (self.state + 1) & W16
        else:
            self.pending = self.state

    def clock_down(self):
        self.state = self.pending

    def get_value(self, index=None):
        return self.state

    def set_value(self, value, index=None):
        self.state = _mask(value, 16)
        self.pending = self.state


class _RAM(SequentialChip):
    SIZE = 8
    ADDR = 3

    def __init__(self):
        self.mem = [0] * self.SIZE
        self.pending = None

    @property
    def INS(self):
        return [('in', 16), ('load', 1), ('address', self.ADDR)]

    OUTS = [('out', 16)]

    def combinational(self, v):
        return {'out': self.mem[v['address']]}

    def clock_up(self, v):
        self.pending = (v['address'], v['in']) if v['load'] else None

    def clock_down(self):
        if self.pending is not None:
            addr, val = self.pending
            self.mem[addr] = val
            self.pending = None

    def get_value(self, index=None):
        return self.mem[index or 0]

    def set_value(self, value, index=None):
        self.mem[index or 0] = _mask(value, 16)


def _make_ram(name, size, addr):
    cls = type(name + 'Chip', (_RAM,), {'SIZE': size, 'ADDR': addr})
    return _seq(name)(cls)


RAM8Chip = _make_ram('RAM8', 8, 3)
RAM64Chip = _make_ram('RAM64', 64, 6)
RAM512Chip = _make_ram('RAM512', 512, 9)
RAM4KChip = _make_ram('RAM4K', 4096, 12)
RAM16KChip = _make_ram('RAM16K', 16384, 14)
ScreenChip = _make_ram('Screen', 8192, 13)


@_seq('ROM32K')
class ROM32KChip(SequentialChip):
    INS = [('address', 15)]
    OUTS = [('out', 16)]

    def __init__(self):
        self.mem = [0] * 32768

    def combinational(self, v):
        return {'out': self.mem[v['address']]}

    def load_program(self, path):
        self.mem = [0] * 32768
        with open(path) as fh:
            i = 0
            for line in fh:
                line = line.strip()
                if not line or line.startswith('//'):
                    continue
                self.mem[i] = int(line, 2)
                i += 1

    def get_value(self, index=None):
        return self.mem[index or 0]

    def set_value(self, value, index=None):
        self.mem[index or 0] = _mask(value, 16)


@_seq('Keyboard')
class KeyboardChip(SequentialChip):
    INS = []
    OUTS = [('out', 16)]

    def __init__(self):
        self.state = 0

    def combinational(self, v):
        return {'out': self.state}

    def get_value(self, index=None):
        return self.state

    def set_value(self, value, index=None):
        self.state = _mask(value, 16)


def builtin_interface(name):
    """Return ``(ins, outs)`` pin declarations for a built-in chip."""
    if name in COMBINATIONAL:
        ins, outs, _ = COMBINATIONAL[name]
        return list(ins), list(outs)
    if name in SEQUENTIAL:
        cls = SEQUENTIAL[name]
        probe = cls()
        ins = probe.INS
        return list(ins), list(cls.OUTS)
    raise KeyError(name)


def is_builtin(name):
    return name in COMBINATIONAL or name in SEQUENTIAL

