    OUT sum, carry;
    PARTS:
    HalfAdder(a=a, b=b, sum=partialSum, carry=carry1);
    HalfAdder(a=partialSum, b=c, sum=sum, carry=carry2);
    Or(a=carry1, b=carry2, out=carry);
