    FullAdder(a=a[10], b=b[10], c=c9,     sum=out[10], carry=c10);
    FullAdder(a=a[11], b=b[11], c=c10,    sum=out[11], carry=c11);
    FullAdder(a=a[12], b=b[12], c=c11,    sum=out[12], carry=c12);
    FullAdder(a=a[13], b=b[13], c=c12,    sum=out[13], carry=c13);
    FullAdder(a=a[14], b=b[14], c=c13,    sum=out[14], carry=c14);
    FullAdder(a=a[15], b=b[15], c=c14,    sum=out[15], carry=c15);
}

// File name: projects/02/Inc16.hdl
CHIP Inc16 {
    IN in[16];
    OUT out[16];
    PARTS:
    Add16(a=in, b[0]=true, b[1..15]=false, out=out);
}

// ALU (Arithmetic Logic Unit)
// The ALU computes one of the following functions:
// x+y, x-y, y-x, 0, 1, -1, x, y, -x, -y, !x, !y,
// x+1, y+1, x-1, y-1, x&y, x|y
// based on 6 input bits (zx,nx,zy,ny,f,no)
// In addition, it computes two 1-bit outputs:
// if out==0, zr=1; else zr=0
// if out<0, ng=1; else ng=0

CHIP ALU {
    IN
        x[16], y[16],
        zx, nx, zy, ny, f, no;
    OUT
        out[16],
        zr, ng;

    PARTS:
    // zx: zero the x input
    Mux16(a=x, b=false, sel=zx, out=xZeroed);
    // nx: negate the x input
    Not16(in=xZeroed, out=xNegated);
    Mux16(a=xZeroed, b=xNegated, sel=nx, out=xFinal);

    // zy: zero the y input
    Mux16(a=y, b=false, sel=zy, out=yZeroed);
    // ny: negate the y input
    Not16(in=yZeroed, out=yNegated);
    Mux16(a=yZeroed, b=yNegated, sel=ny, out=yFinal);

    // f: 1 -> x+y, 0 -> x&y
    Add16(a=xFinal, b=yFinal, out=xPlusY);
    And16(a=xFinal, b=yFinal, out=xAndY);
    Mux16(a=xAndY, b=xPlusY, sel=f, out=fOut);

    // no: negate the output
    Not16(in=fOut, out=fOutNegated);
    Mux16(a=fOut, b=fOutNegated, sel=no,
          out=out, out[0..7]=outLow, out[8..15]=outHigh, out[15]=ng);

    // zr: 1 iff out == 0
    Or8Way(in=outLow, out=lowAny);
    Or8Way(in=outHigh, out=highAny);
    Or(a=lowAny, b=highAny, out=anyBitSet);
    Not(in=anyBitSet, out=zr);
}

