// instruction[15]: 0 -> A-instruction (@value), 1 -> C-instruction.
Not(in=instruction[15], out=isAInstruction);

// The A register takes the instruction itself (A-instruction) or the
// ALU output (C-instruction whose destination includes A).
Mux16(a=instruction, b=aluOut, sel=instruction[15], out=aRegisterIn);
And(a=instruction[15], b=instruction[5], out=destA);
Or(a=isAInstruction, b=destA, out=loadA);
ARegister(in=aRegisterIn, load=loadA, out=aValue, out[0..14]=addressM);

// The D register is only written by a C-instruction whose dest has D.
And(a=instruction[15], b=instruction[4], out=loadD);
DRegister(in=aluOut, load=loadD, out=dValue);

// instruction[12] (the "a" bit) selects A or M as the ALU's y input.
Mux16(a=aValue, b=inM, sel=instruction[12], out=aluY);

ALU(x=dValue, y=aluY,
    zx=instruction[11], nx=instruction[10],
    zy=instruction[9],  ny=instruction[8],
    f=instruction[7],   no=instruction[6],
    out=aluOut, out=outM, zr=zr, ng=ng);

// Write to M only for a C-instruction whose dest includes M.
And(a=instruction[15], b=instruction[3], out=writeM);

// Jump logic: instruction[2]=j1 (out<0), [1]=j2 (out==0), [0]=j3 (out>0).
Or(a=zr, b=ng, out=notPositive);
Not(in=notPositive, out=positive);
And(a=instruction[0], b=positive, out=jumpGT);
And(a=instruction[1], b=zr, out=jumpEQ);
And(a=instruction[2], b=ng, out=jumpLT);
Or(a=jumpGT, b=jumpEQ, out=jumpGE);
Or(a=jumpGE, b=jumpLT, out=jumpCondition);
And(a=instruction[15], b=jumpCondition, out=jump);

PC(in=aValue, load=jump, inc=true, reset=reset, out[0..14]=pc);

