// Each pass over the loop samples the keyboard, picks the fill color
// (0 = white, -1 = black) and writes it to all 8192 words of the screen
// memory map, so a change in the keyboard state is picked up by the pass
// that follows it.

(MAIN)
   @SCREEN
   D=A
   @address
   M=D              // address = SCREEN (first word of the screen map)
   @8192
   D=A
   @n
   M=D              // n = 8192 (words left to paint)

   @KBD
   D=M
   @BLACK
   D;JNE            // a key is pressed -> paint black
   @color
   M=0              // color = white
   @PAINT
   0;JMP
(BLACK)
   @color
   M=-1             // color = black

(PAINT)
   @color
   D=M
   @address
   A=M
   M=D              // Screen[address] = color
   @address
   M=M+1            // address = address + 1
   @n
   MD=M-1           // n = n - 1
   @PAINT
   D;JGT            // more words to paint?
   @MAIN
   0;JMP            // start over: re-sample the keyboard

