import sys, random
sys.path.insert(0, '/workspace/agent_tests')
from hdl.simulator import Simulator
import hdl.builtins as bi

W=0xFFFF
def sgn(v): return v-0x10000 if v & 0x8000 else v

fails=[]
def chk(name, cond, msg):
    if not cond: fails.append(f'{name}: {msg}')

# --- project 02 combinational vs builtin oracle ---
for chip, dirn in [('HalfAdder','02'),('FullAdder','02'),('Add16','02'),('Inc16','02'),('ALU','02')]:
    s = Simulator(f'/workspace/projects/{dirn}/{chip}.hdl')
    ins = {p.name: p.width for p in s.chip.ins}
    ref = bi.COMBINATIONAL[chip][2]
    rnd = random.Random(7)
    vectors=[]
    if chip in ('HalfAdder','FullAdder'):
        n=len(ins)
        for m in range(1<<n):
            vectors.append({p:(m>>i)&1 for i,p in enumerate(ins)})
    elif chip=='Inc16':
        vals=[0,1,0xFFFF,0x8000,0x7FFF,0xFFFE,12345]+[rnd.getrandbits(16) for _ in range(400)]
        vectors=[{'in':v} for v in vals]
    elif chip=='Add16':
        edge=[0,1,0xFFFF,0x8000,0x7FFF,0xAAAA,0x5555]
        for a in edge:
            for b in edge: vectors.append({'a':a,'b':b})
        vectors += [{'a':rnd.getrandbits(16),'b':rnd.getrandbits(16)} for _ in range(400)]
    else: # ALU
        edge=[0,1,0xFFFF,0x8000,0x7FFF,0xAAAA,0x5555,17,0xFFF0]
        for ctrl in range(64):
            c={'zx':(ctrl>>5)&1,'nx':(ctrl>>4)&1,'zy':(ctrl>>3)&1,'ny':(ctrl>>2)&1,'f':(ctrl>>1)&1,'no':ctrl&1}
            for x in edge:
                for y in edge:
                    v=dict(c); v['x']=x; v['y']=y; vectors.append(v)
    bad=0
    for v in vectors:
        for p,val in v.items(): s.set_pin(p, val)
        exp = ref(v)
        for op, ev in exp.items():
            got = s.get_pin(op)
            if got != ev:
                bad += 1
                if bad<=3: fails.append(f'{chip}: {v} pin {op} got {got} want {ev}')
    print(('OK  ' if bad==0 else 'BAD ')+f'{chip} ({len(vectors)} vectors, {bad} mismatches)')

print('FAILURES:' if fails else 'ALL COMBINATIONAL OK')
for f in fails[:20]: print('  ',f)
