"""Minimal independent Hack assembler + emulator (cross-check oracle)."""
import re, sys

COMP = {'0':'0101010','1':'0111111','-1':'0111010','D':'0001100','A':'0110000','!D':'0001101',
 '!A':'0110001','-D':'0001111','-A':'0110011','D+1':'0011111','A+1':'0110111','D-1':'0001110',
 'A-1':'0110010','D+A':'0000010','A+D':'0000010','D-A':'0010011','A-D':'0000111','D&A':'0000000',
 'A&D':'0000000','D|A':'0010101','A|D':'0010101',
 'M':'1110000','!M':'1110001','-M':'1110011','M+1':'1110111','M-1':'1110010','D+M':'1000010',
 'M+D':'1000010','D-M':'1010011','M-D':'1000111','D&M':'1000000','M&D':'1000000','D|M':'1010101','M|D':'1010101'}
DEST = {None:'000','':'000','M':'001','D':'010','MD':'011','DM':'011','A':'100','AM':'101','MA':'101',
 'AD':'110','DA':'110','AMD':'111','ADM':'111','MAD':'111','MDA':'111','DAM':'111','DMA':'111'}
JUMP = {None:'000','':'000','JGT':'001','JEQ':'010','JGE':'011','JLT':'100','JNE':'101','JLE':'110','JMP':'111'}
PRE = {'SP':0,'LCL':1,'ARG':2,'THIS':3,'THAT':4,'SCREEN':16384,'KBD':24576}
for i in range(16): PRE['R%d'%i]=i

def clean(path):
    out=[]
    for line in open(path):
        line=line.split('//')[0].strip().replace(' ','').replace('\t','')
        if line: out.append(line)
    return out

def assemble(path):
    lines=clean(path)
    sym=dict(PRE); pc=0; body=[]
    for l in lines:
        if l.startswith('('):
            sym[l[1:-1]]=pc
        else:
            body.append(l); pc+=1
    nxt=16; code=[]
    for l in body:
        if l.startswith('@'):
            t=l[1:]
            if t.isdigit(): v=int(t)
            else:
                if t not in sym: sym[t]=nxt; nxt+=1
                v=sym[t]
            code.append('0'+format(v,'015b'))
        else:
            jump=None; dest=None; comp=l
            if ';' in comp: comp,jump=comp.split(';')
            if '=' in comp: dest,comp=comp.split('=')
            code.append('111'+COMP[comp]+DEST[dest]+JUMP[jump])
    return code

class Emu:
    def __init__(self, rom):
        self.rom=[int(x,2) for x in rom]; self.ram=[0]*24577; self.A=0; self.D=0; self.PC=0
    def run(self, n):
        rom=self.rom; ram=self.ram; A=self.A; D=self.D; PC=self.PC; L=len(rom)
        for _ in range(n):
            if PC>=L: break
            ins=rom[PC]
            if ins < 0x8000:
                A=ins; PC+=1; continue
            a=(ins>>12)&1; c=(ins>>6)&0x3F; dst=(ins>>3)&7; jmp=ins&7
            y = ram[A] if a else A
            x = D
            zx=(c>>5)&1; nx=(c>>4)&1; zy=(c>>3)&1; ny=(c>>2)&1; f=(c>>1)&1; no=c&1
            if zx: x=0
            if nx: x=(~x)&0xFFFF
            if zy: y=0
            if ny: y=(~y)&0xFFFF
            out = (x+y)&0xFFFF if f else (x&y)
            if no: out=(~out)&0xFFFF
            if dst&1: ram[A]=out
            if dst&2: D=out
            sv = out-0x10000 if out&0x8000 else out
            do = (jmp&1 and sv>0) or (jmp&2 and sv==0) or (jmp&4 and sv<0)
            if dst&4: A=out
            PC = A if do else PC+1
        self.A=A; self.D=D; self.PC=PC
    def sgn(self,a):
        v=self.ram[a]; return v-0x10000 if v&0x8000 else v

if __name__=='__main__':
    for name in sys.argv[1:]:
        for l in assemble(name): print(l)
